@bobylito what do you mean by:
> this will force the developer to do the integration themselves

You mean the logic or just the style?

My solution was to create a widget that checks each refinement widget for an active state, and if it has one, open it up:
```javascript
const options = this.options;
let once = true;

var openIfRefined = function openIfRefined() {
  return {
    render: function() {
      // Check each refinement widget for an active filter and open it if so
      if (once) { // Only once or this will happen each interaction with the widget
        $(".search-refine > div").each((index, elem) => {
          let refineWidget = $(elem);
          let isOpen = refineWidget
            .find(".ais-refinement-list--item")
            .hasClass("ais-refinement-list--item__active");
          if (isOpen) {
            refineWidget
              .find(".ais-root__collapsible")
              .removeClass("ais-root__collapsed");
            refineWidget.find(".panel-heading").trigger("click");
          }
        });
        once = false;
      }
    }
  };
};

this.search.addWidget(openIfRefined());
```
The React component has its state set to `collapsed: true`. I don't know anything about react, is there any way to update the react component's state externally of the framework?

Right now I am triggering click on load to set it to the correct state in a roundabout way:
```javascript
 ...
 refineWidget.find('.panel-heading').trigger('click');
 ...
```
